create or replace function app_private.can_edit_wedding_project(p_project_id uuid) returns boolean language sql stable security definer set search_path='' as $function$ select exists(select 1 from public.wedding_projects p where p.id=p_project_id and p.owner_customer_id=auth.uid()) or exists(select 1 from public.wedding_project_invitations i where i.project_id=p_project_id and i.invitee_user_id=auth.uid() and i.status='accepted' and i.can_edit and i.can_view and i.expires_at>now()); $function$;
create or replace function app_private.can_upload_wedding_project(p_project_id uuid) returns boolean language sql stable security definer set search_path='' as $function$ select exists(select 1 from public.wedding_projects p where p.id=p_project_id and p.owner_customer_id=auth.uid()) or exists(select 1 from public.wedding_project_invitations i where i.project_id=p_project_id and i.invitee_user_id=auth.uid() and i.status='accepted' and i.can_upload and i.can_view and i.expires_at>now()); $function$;
drop policy if exists "owners and accepted collaborators read projects" on public.wedding_projects;
create policy "owners and accepted collaborators read projects" on public.wedding_projects for select to authenticated using(wedding_projects.owner_customer_id=auth.uid() or exists(select 1 from public.wedding_project_invitations i where i.project_id=wedding_projects.id and i.invitee_user_id=auth.uid() and i.status='accepted' and i.can_view and i.expires_at>now()));
drop policy if exists "customers manage own editor projects" on public.wedding_editor_projects;
create policy "owners and editors manage editor projects" on public.wedding_editor_projects for all to authenticated using(owner_customer_id=auth.uid() or (app_private.can_edit_wedding_project(project_id) and owner_customer_id=(select p.owner_customer_id from public.wedding_projects p where p.id=project_id))) with check(app_private.can_edit_wedding_project(project_id) and owner_customer_id=(select p.owner_customer_id from public.wedding_projects p where p.id=project_id));
drop policy if exists "customers manage own wedding albums" on public.wedding_albums;
create policy "owners and uploaders manage wedding albums" on public.wedding_albums for all to authenticated using(owner_customer_id=auth.uid() or (app_private.can_upload_wedding_project(project_id) and owner_customer_id=(select p.owner_customer_id from public.wedding_projects p where p.id=project_id))) with check(app_private.can_upload_wedding_project(project_id) and owner_customer_id=(select p.owner_customer_id from public.wedding_projects p where p.id=project_id));
drop policy if exists "customers manage own album item references" on public.wedding_album_items;
create policy "owners and uploaders manage album item references" on public.wedding_album_items for all to authenticated using(owner_customer_id=auth.uid() or (app_private.can_upload_wedding_project((select a.project_id from public.wedding_albums a where a.id=album_id)) and owner_customer_id=(select a.owner_customer_id from public.wedding_albums a where a.id=album_id))) with check(app_private.can_upload_wedding_project((select a.project_id from public.wedding_albums a where a.id=album_id)) and owner_customer_id=(select a.owner_customer_id from public.wedding_albums a where a.id=album_id));
drop policy if exists "customers manage own highlight jobs" on public.wedding_ai_highlight_jobs;
create policy "owners and editors manage highlight jobs" on public.wedding_ai_highlight_jobs for all to authenticated using(owner_customer_id=auth.uid() or (app_private.can_edit_wedding_project(project_id) and owner_customer_id=(select p.owner_customer_id from public.wedding_projects p where p.id=project_id))) with check(app_private.can_edit_wedding_project(project_id) and owner_customer_id=(select p.owner_customer_id from public.wedding_projects p where p.id=project_id));
drop policy if exists "customers manage own reel exports" on public.wedding_reel_exports;
create policy "owners and editors manage reel exports" on public.wedding_reel_exports for all to authenticated using(owner_customer_id=auth.uid() or (app_private.can_edit_wedding_project(project_id) and owner_customer_id=(select p.owner_customer_id from public.wedding_projects p where p.id=project_id))) with check(app_private.can_edit_wedding_project(project_id) and owner_customer_id=(select p.owner_customer_id from public.wedding_projects p where p.id=project_id));